def is_balanced(text):
    """Return whether parentheses, square brackets, and curly braces are properly nested and matched."""
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set('([{')
    closing = set(')]}')
    for char in text:
        if char in opening:
            stack.append(char)
        elif char in closing:
            if not stack or stack[-1] != matching[char]:
                return False
            stack.pop()
    return len(stack) == 0
