def dedupe_records(records):
    """Deduplicate records by id, keeping the last occurrence of each id while preserving first-appearance order."""
    if not records:
        return []

    # Track the last index for each id
    last_index = {}
    for i, record in enumerate(records):
        last_index[record['id']] = i

    # Build result preserving order of first appearance of each id
    seen = set()
    result = []
    for record in records:
        rid = record['id']
        if rid not in seen:
            seen.add(rid)
            # Find the last occurrence of this id
            result.append(records[last_index[rid]])

    return result
